<?php
// AUTO-EXTRACTED - do not edit. Regenerated by run.ps1 on every run.
function _sfe_h($s) {
    return htmlspecialchars((string)$s, ENT_QUOTES, 'UTF-8');
}

function _sfe_get($arr, $key, $default) {
    if (is_array($arr) && array_key_exists($key, $arr) && $arr[$key] !== null && $arr[$key] !== '') {
        return $arr[$key];
    }
    return $default;
}

function _sfe_kv_row($label, $value_html) {
    return penumbra_email_row($label, $value_html);
}

function _sfe_resolve_recipients($spec, $owner) {
    $result = array();
    $seen = array();
    $owner = trim((string)$owner);
    if (!is_string($spec)) { $spec = ''; }
    $spec = trim($spec);
    if ($spec === '') { $spec = 'me'; }
    // Splitting on whitespace as well as , and ; is also what keeps a CR/LF in
    // the spec from reaching a header: it becomes a token boundary, and the
    // "Bcc:"-style remainder then fails validation like any other junk token.
    $parts = preg_split('/[,;\s]+/', $spec);
    foreach ($parts as $p) {
        $p = trim($p);
        if ($p === '') { continue; }
        // "me" is this function's own keyword - the one thing the shared rule
        // does not know about. Resolve it to the owner and let the owner take
        // the same path as any other token.
        if (strtolower($p) === 'me') { $p = $owner; }
        // A lone "<addr>" token: the old code passed the brackets through into
        // the header. Unwrap so a spec that used to work still resolves, then
        // validate what is inside.
        if (strlen($p) > 1 && substr($p, 0, 1) === '<' && substr($p, -1) === '>') {
            $p = substr($p, 1, -1);
        }
        $addr = penumbraUnityEmail($p);
        if ($addr === '') { continue; }
        if (isset($seen[$addr])) { continue; }
        $seen[$addr] = true;
        $result[] = $addr;
    }
    return $result;
}

function send_scheduler_failure_email($report_id, $action, $message, $context) {
    static $already_sent = array();
    if (!is_array($context)) { $context = array(); }

    $admin_bcc = 'bplimon@ncsu.edu';

    // De-dupe: at most one email per task per runner invocation. (A single
    // failed run can log more than one failure audit; we only want one email.)
    $task_id = _sfe_get($context, 'task_id', '');
    if ($task_id !== '') {
        $dedupe_key = 'task:' . $task_id;
    } else {
        $dedupe_key = 'msg:' . md5((string)$message);
    }
    if (isset($already_sent[$dedupe_key])) { return array('state' => 'dup'); }
    $already_sent[$dedupe_key] = true;

    // Resolve recipients from the task's notify spec ("me" = owner). The owner's
    // chosen recipients govern failure mail too. Fall back to the admin if nothing
    // resolves (e.g. owner unknown and no explicit address) so a failure always
    // reaches someone - the original behavior.
    $owner = trim((string)_sfe_get($context, 'owner', ''));
    $recips = _sfe_resolve_recipients(_sfe_get($context, 'notify_failure_recipients', 'me'), $owner);
    if (empty($recips)) { $recips = array($admin_bcc); }
    $to = implode(', ', $recips);

    // Per-action framing.
    if ($action === 'SCHEDULE_NOAUTH') {
        $headline  = 'Scheduled task blocked';
        $intro     = 'A scheduled task on your Penumbra report was blocked because a recipient is not authorized to view this private report. The task did not run.';
        $band_bg   = '#8a6d00';
    } else {
        $headline  = 'Scheduled task failed';
        $intro     = 'A scheduled task on your Penumbra report did not complete successfully. The details below should help you diagnose and fix it.';
        $band_bg   = '#a12a2a';
    }

    // One-time draft test (Test Run from new-task mode): the temporary task is
    // already gone, so nothing will retry - say so, and keep the NOAUTH framing
    // for blocked runs.
    $is_transient_test = (_sfe_get($context, 'transient_test', false) === true);
    if ($is_transient_test && $action !== 'SCHEDULE_NOAUTH') {
        $headline = 'One-time test run failed';
        $intro    = 'Your one-time Test Run of a DRAFT scheduled task did not complete successfully. '
                  . 'The draft was not added to the scheduled events and the temporary task removed itself, so nothing will retry automatically - '
                  . 'adjust the settings in the scheduler form and test again. The details below should help you diagnose it.';
    }

    // The report was deleted out from under the task. Unlike every other failure
    // this one is permanent and the runner has already acted on it, so frame it
    // as a state change ("we turned it off") rather than an error to retry.
    $is_missing_report = (_sfe_get($context, 'report_missing', false) === true);
    if ($is_missing_report) {
        if (_sfe_get($context, 'auto_deactivated', false) === true) {
            $headline = 'Scheduled task disabled: report not found';
            $intro    = 'A scheduled task points at a Penumbra report that no longer exists, so it can never run successfully. '
                      . 'The scheduler has disabled the task automatically - it will not run again until you point it at an existing '
                      . 'report and re-enable it. You are receiving this once, rather than on every future run.';
        } else {
            $headline = 'Scheduled task failed: report not found';
            $intro    = 'A scheduled task points at a Penumbra report that no longer exists, so it can never run successfully. '
                      . 'The scheduler tried to disable the task automatically and could not, so it will keep failing on every '
                      . 'scheduled run until you disable or re-point it.';
        }
    }

    // Display fields.
    $task_type  = _sfe_get($context, 'task_type', 'Scheduled task');
    $label      = _sfe_get($context, 'subject', '(untitled task)');
    $short_id   = _sfe_get($context, 'short_id', _sfe_get($context, 'report_short_id', (string)$report_id));
    $cron       = _sfe_get($context, 'cron', '(unknown)');
    $recipients = _sfe_get($context, 'recipients', '');
    $when       = date('Y-m-d H:i:s T');
    if ($is_transient_test) {
        // A draft test has no real schedule (the stored cron may be a
        // placeholder) - don't echo it.
        $cron = 'one-time (immediate)';
    }

    $type_names = array(
        'EMAIL'     => 'Email Report',
        'SNAPSHOT'  => 'Snapshot',
        'DROP_FILE' => 'Drop a File',
        'DB_DUMP'   => 'Dump to Data Source'
    );
    if (isset($type_names[$task_type])) { $type_label = $type_names[$task_type]; }
    else { $type_label = $task_type; }

    // Use the live/public host (same link the report emails use), NOT the
    // internal API host (oitras) the runner calls server-side.
    // Deep-link to the report - except when the report is the thing that's
    // missing, in which case ?id= would land the reader on a dead page and
    // undercut the message. Send them to the repository instead.
    $scheduler_url = 'https://www3.acs.ncsu.edu/sponsor_migration/penumbra/index.php';
    if ($short_id !== '' && $short_id !== null && !$is_missing_report) { $scheduler_url .= '?id=' . rawurlencode((string)$short_id); }
    if ($is_missing_report) { $cta_label = 'Open Penumbra'; }
    else { $cta_label = 'Open the report &amp; scheduler'; }

    if ($owner !== '') { $owner_disp = $owner; } else { $owner_disp = '(unknown)'; }

    // --- Task details table ---
    $rows  = '';
    $rows .= _sfe_kv_row('Task', _sfe_h($type_label) . ' - #' . _sfe_h($task_id));
    $rows .= _sfe_kv_row('Label', _sfe_h($label));
    $rows .= _sfe_kv_row('Report', _sfe_h($short_id));
    $rows .= _sfe_kv_row('Schedule', '<code>' . _sfe_h($cron) . '</code>');
    if ($is_transient_test) {
        $rows .= _sfe_kv_row('Run type', 'One-time test of an unsaved draft (task auto-removed after this run)');
    }
    if ($task_type === 'EMAIL' && $recipients !== '') {
        $rows .= _sfe_kv_row('Recipients', _sfe_h($recipients));
    }
    $rows .= _sfe_kv_row('Owner', _sfe_h($owner_disp));
    $rows .= _sfe_kv_row('When', _sfe_h($when));

    // --- Optional DB_DUMP detail section ---
    $dbdump_section = '';
    $dd = _sfe_get($context, 'db_dump', null);
    if (is_array($dd)) {
        $dd_rows  = '';
        $dd_rows .= _sfe_kv_row('Destination', _sfe_h(_sfe_get($dd, 'destination', '(n/a)')));
        if (array_key_exists('row_count', $dd)) { $dd_rows .= _sfe_kv_row('Rows from report', _sfe_h($dd['row_count'])); }
        $ins = _sfe_get($dd, 'inserts', null);
        if (is_array($ins)) {
            $ins_summary = _sfe_h(_sfe_get($ins, 'successful', '0')) . ' inserted';
            if (isset($ins['failed']) && $ins['failed']) { $ins_summary .= ', ' . _sfe_h($ins['failed']) . ' failed'; }
            $dd_rows .= _sfe_kv_row('Inserts', $ins_summary);
        }
        if (isset($dd['reload_mode'])) { $dd_rows .= _sfe_kv_row('Reload mode', _sfe_h($dd['reload_mode'])); }
        if (isset($dd['error_file'])) { $dd_rows .= _sfe_kv_row('Error location', '<code>' . _sfe_h($dd['error_file']) . '</code>'); }
        $last_stmt = _sfe_get($dd, 'last_statement', '');
        if ($last_stmt !== '') {
            $dd_rows .= _sfe_kv_row('Last statement', '<code style="font-size:11px;">' . _sfe_h(substr((string)$last_stmt, 0, 400)) . '</code>');
        }
        if (isset($dd['duration_ms'])) { $dd_rows .= _sfe_kv_row('Duration', _sfe_h($dd['duration_ms']) . ' ms'); }
        $dbdump_section = penumbra_email_section('Dump details', penumbra_email_kv_table($dd_rows));
    }

    // --- Full technical context (bounded). Plain json_encode for 5.3 safety. ---
    $json = json_encode($context);
    if ($json === false) { $json = '(context not serializable)'; }
    if (strlen($json) > 6000) { $json = substr($json, 0, 6000) . ' ... [truncated]'; }

    $error_html = nl2br(_sfe_h($message));

    // --- Assemble the email ---------------------------------------------------
    // Markup now comes from penumbra_email_shell.php so the watchdog's alerts and
    // these failure notices share one visual language instead of drifting apart.
    // The shell emits byte-identical output to the inline version this replaced,
    // proven by penumbra_tests\emailshell (five framing branches, before/after
    // diff). Transport below is deliberately NOT shared - see the note there.
    $html  = penumbra_email_open($headline, $band_bg);
    $html .= penumbra_email_intro($intro);
    $html .= penumbra_email_callout('What went wrong', $error_html);
    $html .= penumbra_email_section('Task details', penumbra_email_kv_table($rows));
    $html .= $dbdump_section;   // optional, already assembled above
    $html .= penumbra_email_section('Full technical context', penumbra_email_pre($json));
    $html .= penumbra_email_cta($scheduler_url, $cta_label);
    $html .= penumbra_email_close('You are receiving this because you\'re a failure-notification recipient for this scheduled task (set in the scheduler\'s On Completion options). This is an automated message from the Penumbra scheduler - replies are not monitored.');

    // --- Subject ---
    $subject_label = preg_replace('/[\r\n]+/', ' ', (string)$label);
    $subject = '[Penumbra] ' . $headline . ': ' . $subject_label;
    if ($task_id !== '') { $subject .= ' (task #' . $task_id . ')'; }

    // --- Headers + MIME body ---
    // Wrap the HTML in a multipart/mixed part encoded quoted-printable - the same
    // structure the report emails use (see the EMAIL send path). Quoted-printable's
    // soft line breaks keep mail servers / Gmail from injecting spaces or hard
    // breaks into the long, newline-free HTML lines (which would otherwise surface
    // as literal characters in the rendered message). BCC the admin only when the
    // owner is the To; otherwise To is already the admin (avoids a duplicate).
    $boundary = '----=_Part_' . md5(uniqid(mt_rand(), true));
    $admin_is_recipient = false;
    foreach ($recips as $_r) {
        if (strtolower(trim($_r)) === strtolower($admin_bcc)) { $admin_is_recipient = true; break; }
    }
    $headers  = "MIME-Version: 1.0\r\n";
    $headers .= "From: Penumbra Scheduler <penumbra-scheduler@ncsu.edu>\r\n";
    if (!$admin_is_recipient) { $headers .= "Bcc: " . $admin_bcc . "\r\n"; }
    $headers .= "X-Auto-Response-Suppress: All\r\n";
    $headers .= "Auto-Submitted: auto-generated\r\n";
    $headers .= "Message-ID: <" . md5(uniqid(mt_rand(), true)) . "@ncsu.edu>\r\n";
    $headers .= "Content-Type: multipart/mixed;\r\n boundary=\"{$boundary}\"\r\n";

    $body  = "--{$boundary}\r\n";
    $body .= "Content-Type: text/html; charset=UTF-8\r\n";
    $body .= "Content-Transfer-Encoding: quoted-printable\r\n";
    $body .= "\r\n";
    $body .= pnb_capture_html($html) . "\r\n";
    $body .= "--{$boundary}--\r\n";

    $receipt_bcc = '';
    if (!$admin_is_recipient) { $receipt_bcc = $admin_bcc; }
    if (pnb_fake_mail($to, $subject, $body, $headers)) {
        $log_bcc = '';
        if (!$admin_is_recipient) { $log_bcc = ' (bcc ' . $admin_bcc . ')'; }
        log_scheduler("  Failure notification emailed to $to$log_bcc [$dedupe_key].");
        return array('state' => 'sent', 'to' => $to, 'bcc' => $receipt_bcc);
    } else {
        log_scheduler("  Warning: failure-notification mail() returned false (to=$to).");
        return array('state' => 'failed', 'to' => $to, 'bcc' => $receipt_bcc);
    }
}
